-- MemberJunction PostgreSQL Migration — V202608120830__v6.1.x__TaskType_Name_Unique.sql
-- Generated by the split-and-regenerate pipeline, then HAND-CORRECTED (see below).
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE SCHEMA IF NOT EXISTS __mj;
SET search_path TO __mj, public;
SET standard_conforming_strings = on;

-- HAND-CORRECTED. The transpiler's output for this migration had four defects, each of which
-- would have shipped silently on PostgreSQL only:
--
--  1. THE UNIQUE INDEX WAS MISSING ENTIRELY. `CREATE UNIQUE INDEX UQ_TaskType_Name` sits inside
--     an `IF NOT EXISTS (SELECT 1 FROM sys.indexes ...)` guard; the guard was reported as
--     unhandled and the CREATE inside it went with it. What survived was only the DEFENSIVE
--     de-duplication -- so the counterpart did the cleanup whose sole purpose is to make the
--     index creatable, and then did not create the index. PostgreSQL would have been left
--     without the constraint the migration exists to add, and TaskType.Name non-unique there
--     forever, reintroducing exactly the never-settles-stays-Paused failure documented in the
--     T-SQL original. `CREATE UNIQUE INDEX IF NOT EXISTS` is the native equivalent of the guard.
--
--  2. `DELETE "tt" FROM __mj."TaskType" AS "tt" INNER JOIN ...` is not valid PostgreSQL. The
--     T-SQL delete-through-a-join form has no PG equivalent; PG spells it `DELETE FROM ... USING`.
--     As emitted, the migration was a syntax error at that statement.
--
--  3. `SELECT ... INTO TEMPORARY "TaskTypeMerge"` cannot mean "create a temp table" here. Inside
--     a `DO $$ ... $$` block the body is PL/pgSQL, where `INTO` is *variable assignment* -- the
--     statement does not create a table, and every later reference to "TaskTypeMerge" fails. The
--     PL/pgSQL spelling is `CREATE TEMP TABLE ... AS SELECT ...`.
--
--  4. The `sp_addextendedproperty` call documents an INDEX (`@level2type = N'INDEX'`), but it was
--     converted to `COMMENT ON TABLE __mj."TaskType"`. That is not merely mis-targeted: it
--     OVERWRITES the TaskType table's own description with a description of the index. PG's
--     `COMMENT ON INDEX` is the correct target.
--
-- The de-duplication CTE is also re-expressed with FIRST_VALUE over a partition rather than the
-- transpiled correlated-subquery-under-GROUP-BY. Same semantics -- every row that is not its
-- name's earliest-created row is a duplicate to be merged away -- in one pass and without relying
-- on PG's functional-dependency analysis to accept a correlated subquery in a grouped select list.

-- ---------------------------------------------------------------------------------------------
-- 1. Merge any duplicate names onto their oldest row, so the index below can be created.
--    Defensive and conservative: on a database with no duplicates this does nothing at all.
-- ---------------------------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM __mj."TaskType" GROUP BY "Name" HAVING COUNT(*) > 1) THEN
    RAISE NOTICE 'TaskType has duplicate Names; merging each onto its oldest row before adding the unique index.';

    -- The survivor of each name is the earliest-created row -- earliest rather than "any", because
    -- it is the one existing graphs are most likely already stamped with.
    CREATE TEMP TABLE "TaskTypeMerge" AS
    WITH "Ranked" AS (
        SELECT
            "ID",
            "Name",
            FIRST_VALUE("ID") OVER (
                PARTITION BY "Name"
                ORDER BY "__mj_CreatedAt" ASC, "ID" ASC
            ) AS "SurvivorID"
        FROM __mj."TaskType"
    )
    SELECT "Name", "SurvivorID", "ID" AS "DuplicateID"
    FROM "Ranked"
    WHERE "ID" <> "SurvivorID";

    -- Repoint everything that references a duplicate. Tasks first: these are the rows whose
    -- invisibility to the sweep is the whole reason this migration exists.
    UPDATE __mj."Task" AS "t"
    SET "TypeID" = "m"."SurvivorID"
    FROM "TaskTypeMerge" AS "m"
    WHERE "m"."DuplicateID" = "t"."TypeID";

    -- Self-reference: a duplicate may be some other type's parent.
    UPDATE __mj."TaskType" AS "tt"
    SET "ParentID" = "m"."SurvivorID"
    FROM "TaskTypeMerge" AS "m"
    WHERE "m"."DuplicateID" = "tt"."ParentID";

    DELETE FROM __mj."TaskType" AS "tt"
    USING "TaskTypeMerge" AS "m"
    WHERE "m"."DuplicateID" = "tt"."ID";

    DROP TABLE "TaskTypeMerge";
  END IF;
END $$;

-- ---------------------------------------------------------------------------------------------
-- 2. The constraint itself -- the point of the migration.
-- ---------------------------------------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS "UQ_TaskType_Name" ON __mj."TaskType" ("Name");

COMMENT ON INDEX __mj."UQ_TaskType_Name" IS 'A task type is identified by its Name: the dispatcher resolves ''AI Workflow'' by name to scope every sweep arm and both payload-writing guards, so two rows sharing a name let different processes bind different IDs — and a graph stamped with the other one is invisible to the sweep, never settles, and leaves its submitting run Paused forever, with no error anywhere.';
